window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0259ec8572303a3f"]={"versions": [{"id": "FIG-0259ec8572303a3f", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-ECU-Konfigurationsparameter (BSW-Metamodell / ECUC-Parameterdefinition) für das BSW-Modul <code>Dem</code> (Diagnostic Event Manager) innerhalb der AUTOSAR Classic Platform. Das Diagramm modelliert die strukturelle Zuordnung und Auswahl der ereignisspezifischen Entprell-Algorithmen (Debounce Algorithms) zu Diagnose-Event-Parametern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Konfigurationscontainer und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DemEventParameter : EcucParamConfContainerDef</code> (Multiplizität: <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 65535</code>): Repräsentiert die Konfiguration eines einzelnen Diagnose-Events.\n</li><li><code>DemDebounceAlgorithmClass : EcucChoiceContainerDef</code> (Multiplizität: <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>): Choice-Container, der über eine Kompositionsbeziehung mit Rollenbezeichnung <code>+subContainer</code> in <code>DemEventParameter</code> eingebettet ist. Erzwingt die Auswahl genau einer Entprellstrategie pro Event.\n</li><li>Zur Auswahl stehende Kind-Container (<code>+choice</code>), jeweils als <code>EcucParamConfContainerDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code> per Komposition an <code>DemDebounceAlgorithmClass</code> angebunden:\n<ul class=\"fig-list\"><li><code>DemDebounceTimeBase : EcucParamConfContainerDef</code>: Zeitbasierte Entprellung.\n</li><li><code>DemDebounceCounterBased : EcucParamConfContainerDef</code>: Zählerbasierte Entprellung.\n</li><li><code>DemDebounceMonitorInternal : EcucParamConfContainerDef</code>: Monitor-interne Entprellung durch den SW-C- bzw. BSW-Monitor selbst.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Konfigurationsmetamodell ohne dynamische Laufzeitsequenzen. Zur Konfigurations- bzw. Generierungszeit bestimmt die Auswahl innerhalb des Choice-Containers <code>DemDebounceAlgorithmClass</code>, welcher Entprellmechanismus bei Statusmeldungen (<code>Dem_SetEventStatus</code>) für das jeweilige Event zur Auswertung kommt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Konfigurationsstruktur für AUTOSAR-Dem-Generatoren und BSW-Konfigurationstools. Jedes konfigurierte <code>DemEventParameter</code> muss zwingend genau eine Instanz der <code>DemDebounceAlgorithmClass</code> und damit exakt einen der drei konfigurierten Entprellalgorithmen (<code>DemDebounceTimeBase</code>, <code>DemDebounceCounterBased</code> oder <code>DemDebounceMonitorInternal</code>) enthalten. Die maximale Anzahl konfigurierbarer Events ist auf 65535 begrenzt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6e9ff8581ba85992", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-ECU-Konfigurationsparameter (BSW-Metamodell / ECUC-Parameterdefinition) für das BSW-Modul <code>Dem</code> (Diagnostic Event Manager) innerhalb der AUTOSAR Classic Platform. Das Diagramm modelliert die strukturelle Zuordnung und Auswahl der ereignisspezifischen Entprell-Algorithmen (Debounce Algorithms) zu Diagnose-Event-Parametern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Konfigurationscontainer und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DemEventParameter : EcucParamConfContainerDef</code> (Multiplizität: <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 65535</code>): Repräsentiert die Konfiguration eines einzelnen Diagnose-Events.\n</li><li><code>DemDebounceAlgorithmClass : EcucChoiceContainerDef</code> (Multiplizität: <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>): Choice-Container, der über eine Kompositionsbeziehung mit Rollenbezeichnung <code>+subContainer</code> in <code>DemEventParameter</code> eingebettet ist. Erzwingt die Auswahl genau einer Entprellstrategie pro Event.\n</li><li>Zur Auswahl stehende Kind-Container (<code>+choice</code>), jeweils als <code>EcucParamConfContainerDef</code> mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code> per Komposition an <code>DemDebounceAlgorithmClass</code> angebunden:\n<ul class=\"fig-list\"><li><code>DemDebounceTimeBase : EcucParamConfContainerDef</code>: Zeitbasierte Entprellung.\n</li><li><code>DemDebounceCounterBased : EcucParamConfContainerDef</code>: Zählerbasierte Entprellung.\n</li><li><code>DemDebounceMonitorInternal : EcucParamConfContainerDef</code>: Monitor-interne Entprellung durch den SW-C- bzw. BSW-Monitor selbst.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Konfigurationsmetamodell ohne dynamische Laufzeitsequenzen. Zur Konfigurations- bzw. Generierungszeit bestimmt die Auswahl innerhalb des Choice-Containers <code>DemDebounceAlgorithmClass</code>, welcher Entprellmechanismus bei Statusmeldungen (<code>Dem_SetEventStatus</code>) für das jeweilige Event zur Auswertung kommt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Konfigurationsstruktur für AUTOSAR-Dem-Generatoren und BSW-Konfigurationstools. Jedes konfigurierte <code>DemEventParameter</code> muss zwingend genau eine Instanz der <code>DemDebounceAlgorithmClass</code> und damit exakt einen der drei konfigurierten Entprellalgorithmen (<code>DemDebounceTimeBase</code>, <code>DemDebounceCounterBased</code> oder <code>DemDebounceMonitorInternal</code>) enthalten. Die maximale Anzahl konfigurierbarer Events ist auf 65535 begrenzt.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0259ec8572303a3f", "to": "FIG-6e9ff8581ba85992", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>DemEventParameter</code>: Leerzeichen vor dem Doppelpunkt in der Container-Typdeklaration entfernt (<code>DemEventParameter :</code> -&gt; <code>DemEventParameter:</code>).\n</li><li><code>DemDebounceAlgorithmClass</code>: Leerzeichen vor dem Doppelpunkt in der Container-Typdeklaration entfernt (<code>DemDebounceAlgorithmClass :</code> -&gt; <code>DemDebounceAlgorithmClass:</code>).\n</li><li><code>DemDebounceTimeBase</code>: Leerzeichen vor dem Doppelpunkt in der Container-Typdeklaration entfernt (<code>DemDebounceTimeBase :</code> -&gt; <code>DemDebounceTimeBase:</code>).\n</li><li><code>DemDebounceCounterBased</code>: Leerzeichen vor dem Doppelpunkt in der Container-Typdeklaration entfernt (<code>DemDebounceCounterBased :</code> -&gt; <code>DemDebounceCounterBased:</code>).\n</li><li><code>DemDebounceMonitorInternal</code>: Leerzeichen vor dem Doppelpunkt in der Container-Typdeklaration entfernt (<code>DemDebounceMonitorInternal :</code> -&gt; <code>DemDebounceMonitorInternal:</code>).\n</li></ul>"}]};
